-- 32 fixed full-precision fixtures generated by independent JS BigInt arithmetic:
-- four date orientations x eight visible indices; no normative SQL loaded.
-- Assert exact 46 length, bounds, invalid inputs, SQL-only purity and bootstrap isolation.
BEGIN;
CREATE TEMP TABLE stage02_visible_assertions(
    test_name text PRIMARY KEY,ok boolean NOT NULL CHECK(ok)
);
WITH cases(label,calculation_day,target_day) AS (
  VALUES
   ('same', -15055671::numeric,-15055671::numeric),
   ('forward', -15055674::numeric,-15055669::numeric),
   ('reverse', -15055669::numeric,-15055674::numeric),
   ('large', -15055671::numeric,-15055671::numeric+pastafari_sql_tamil.save_modulus())
), vectors AS MATERIALIZED (
  SELECT label,pastafari_sql_tamil.visible_drops(
    pastafari_sql_tamil.work_counts(calculation_day,target_day)) AS drops
  FROM cases
), fixtures(label,i,expected) AS (
  VALUES
('same',1,56644603826892212324764499696091907135::numeric),
('same',2,68953726611520950166075866637346981907::numeric),
('same',3,156248044892837952734926746199182095252::numeric),
('same',7,34873345010175649611113753130319650900::numeric),
('same',8,138231725666891155966427565094054001176::numeric),
('same',23,148220932267785450843743469835388746886::numeric),
('same',45,66534692871825902579488225144948967863::numeric),
('same',46,141872771689426650819909896585756512282::numeric),
('forward',1,149777815151458992626285861266496228160::numeric),
('forward',2,134567490305340080700589925492602304722::numeric),
('forward',3,132200885193554059492741484551679378015::numeric),
('forward',7,37917755298568490011931264114818610857::numeric),
('forward',8,111588360608683393149199726116747728837::numeric),
('forward',23,169695684362794464276956026588074215316::numeric),
('forward',45,157369348898419665606719151074509308306::numeric),
('forward',46,54639763838797228928557262466035205504::numeric),
('reverse',1,169031683725473003751978986627170723618::numeric),
('reverse',2,19342426624404998457000810592541861914::numeric),
('reverse',3,18852028520758247401008896070166709123::numeric),
('reverse',7,102649900783748045550193643399163028377::numeric),
('reverse',8,75707642821441232951177895994996466586::numeric),
('reverse',23,156958810975831217054121325925680492487::numeric),
('reverse',45,132541872251681311207158943551578244168::numeric),
('reverse',46,79297500941803674742937481797209871455::numeric),
('large',1,43361295818118712994835375134984623622::numeric),
('large',2,63083992719392103278760838444929637933::numeric),
('large',3,76140359912464759988702323750802900331::numeric),
('large',7,4452111863281342367403794017037953637::numeric),
('large',8,55343705536929951028347792052277407268::numeric),
('large',23,6417540488673729947637906395747008100::numeric),
('large',45,18732160462472233221946397152817998259::numeric),
('large',46,66531025890577323093388565739202776676::numeric)
)
INSERT INTO stage02_visible_assertions(test_name,ok)
SELECT 'fixture:'||f.label||':'||f.i,v.drops[f.i]=f.expected
  FROM fixtures f JOIN vectors v USING(label)
UNION ALL
SELECT 'length:'||label,coalesce(array_length(drops,1),0)=46 FROM vectors
UNION ALL
SELECT 'bounds:'||label,
    (SELECT bool_and(x BETWEEN 1 AND pastafari_sql_tamil.save_modulus())
       FROM unnest(drops) AS t(x))
    FROM vectors
UNION ALL
SELECT 'invalid-zero',pastafari_sql_tamil.one_visible_drop(0,pastafari_sql_tamil.work_counts(-15055671,-15055671),ARRAY[]::numeric[]) IS NULL
UNION ALL
SELECT 'invalid-47',pastafari_sql_tamil.one_visible_drop(47,pastafari_sql_tamil.work_counts(-15055671,-15055671),ARRAY[]::numeric[]) IS NULL
UNION ALL
SELECT 'invalid-prefix',pastafari_sql_tamil.one_visible_drop(2,pastafari_sql_tamil.work_counts(-15055671,-15055671),ARRAY[]::numeric[]) IS NULL
UNION ALL
SELECT 'null-counts',pastafari_sql_tamil.visible_drops(NULL::pastafari_sql_tamil.work_counts) IS NULL
UNION ALL
SELECT 'fractional-day',pastafari_sql_tamil.visible_drops(pastafari_sql_tamil.work_counts(-15055670.5,-15055671)) IS NULL
UNION ALL
SELECT 'null-prefix',pastafari_sql_tamil.one_visible_drop(1,pastafari_sql_tamil.work_counts(-15055671,-15055671),NULL::numeric[]) IS NULL
UNION ALL
SELECT 'reference-namespace-absent',
    position('pastafari_sql_tamil_test' in pg_get_functiondef(
      'pastafari_sql_tamil.visible_drops(pastafari_sql_tamil.work_counts)'::regprocedure))=0
UNION ALL
SELECT 'reference-namespace-absent-single',
    position('pastafari_sql_tamil_test' in pg_get_functiondef(
      'pastafari_sql_tamil.one_visible_drop(integer,pastafari_sql_tamil.work_counts,numeric[])'::regprocedure))=0
UNION ALL
SELECT 'SQL-language',
    (SELECT l.lanname='sql' FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang
    WHERE p.oid='pastafari_sql_tamil.visible_drops(pastafari_sql_tamil.work_counts)'::regprocedure)
UNION ALL
SELECT 'immutable',
    (SELECT p.provolatile='i' FROM pg_proc p
    WHERE p.oid='pastafari_sql_tamil.visible_drops(pastafari_sql_tamil.work_counts)'::regprocedure)
UNION ALL
SELECT 'full-calendar-not-implemented',
    (SELECT count(*)=0 FROM pastafari_sql_tamil.calendar_date_spaghetti(-15055671,-15055671));
SELECT 'visible native assertions' AS status,count(*) AS assertion_count
FROM stage02_visible_assertions;
COMMIT;
